"""Detection dispatch over the methods named in a signed `provenmark.params/1` record (detectors are imported on
demand; a method whose detector is not installed is reported as unavailable), and the Fisher combination used as
the decision statistic. Exported for third-party verification; embedding, tracing and release
creation are not part of this package.
"""
from __future__ import annotations

import hashlib
import importlib
import numpy as np
import pandas as pd
from .addressing import AddressSpec, time_seconds


# Methods whose p-value is NOT valid for arbitrary data and is therefore reported for information only, never part
# of the decision (packaging/SPLIT_PLAN.md R11): tone's parametric p assumes noise around the keyed frequency; on data
# with natural spectral lines an innocent key's frequency can land on a line (measured: P(p <= 1e-6) = 2.4 %).
INFO_ONLY_METHODS = frozenset({"tone"})


ALL_METHODS = ("ssw", "csw", "tone", "gl", "evt", "cue", "xc", "xcue")


PARAMS_FORMAT = "provenmark.params/1"


def _time_axis(df, addr):
    t = time_seconds(df, addr)
    return t if t is not None else np.arange(len(df), dtype=np.float64)


def detect_with_keys(df: pd.DataFrame, keys: dict[str, bytes], params: dict, max_shift: int = 0) -> dict:
    addr = AddressSpec.from_dict(params["address"])
    res = {}
    m = params["methods"]
    def both(fn):
        """Plain detector AND +-max_shift offset search, 2 x min p (Bonferroni). The search recovers re-stamped
        copies and marks displaced by blind-spot denoisers; the plain detector keeps full power otherwise
        (R2_RESULTS 2.15)."""
        r0 = fn(0)
        if not max_shift:
            return r0
        r1 = fn(max_shift)
        best = r1 if r1["p"] < r0["p"] else r0
        return {**best, "p": float(min(1.0, 2 * min(r0["p"], r1["p"]))),
                "offset_search": {"max_shift": max_shift, "p_plain": r0["p"], "p_offset": r1["p"],
                                  "shift": r1.get("shift", 0)}}

    for name in _DETECT_ORDER:
        if name not in m or name not in keys:
            continue
        mod = detector_module(name)
        if mod is None:                       # this installation does not ship the detector (see detector_module)
            continue
        call = _DETECT_CALL[name]
        if name in _SHIFTABLE:
            res[name] = both(lambda s_: call(mod, df, keys[name], addr, m[name], s_))
        else:
            res[name] = call(mod, df, keys[name], addr, m[name], 0)
    return res


# ---- detector registry: each method's detector is imported only when a release record uses it, so an installation
# (e.g. the public verification package) can ship a subset of detectors and report the others as unavailable instead
# of failing at import. Order = the historical evaluation order (keeps result dicts and float sums identical).
_DETECT_ORDER = ("ssw", "csw", "gl", "xc", "xcue", "cue", "evt", "tone")


_SHIFTABLE = {"ssw", "csw"}


_DETECT_CALL = {
    "ssw": lambda mod, df, k, addr, p, s: mod.detect(df, k, addr, p["columns"], max_shift=s),
    "csw": lambda mod, df, k, addr, p, s: mod.detect(df, k, addr, p["columns"], p["chip"], max_shift=s),
    "gl": lambda mod, df, k, addr, p, s: mod.detect(df, k, p["columns"]),
    "xc": lambda mod, df, k, addr, p, s: mod.detect(df, k, p),
    "xcue": lambda mod, df, k, addr, p, s: mod.detect(df, k, p),
    "cue": lambda mod, df, k, addr, p, s: mod.detect(df, k, p),
    "evt": lambda mod, df, k, addr, p, s: mod.detect(df, k, addr, p["columns"]),
    "tone": lambda mod, df, k, addr, p, s: mod.detect(df, k, _time_axis(df, addr), p),
}


def detector_module(name: str):
    """The detector module for a method, or None if the method is unknown or not installed."""
    if name not in _DETECT_CALL:
        return None
    full = f"{__package__}.methods.{name}"
    try:
        return importlib.import_module(full)
    except ModuleNotFoundError as e:
        if e.name == full:                    # the detector itself is absent; a missing dependency still raises
            return None
        raise


def available_detectors() -> list[str]:
    return [n for n in _DETECT_ORDER if detector_module(n) is not None]


def combine(results: dict) -> dict:
    """Fisher-combine method p-values: the DECISION statistic. Methods use independently derived keys, so given the
    suspect data their statistics are independent and Fisher is exact. Fisher was the best rule measured: under
    5-licensee collusion it attributes 22/30 vs 17/30 for 2 x min p, and loses almost nothing when one method is
    destroyed (R2_RESULTS 2.15). The min p with Bonferroni is reported for information only; using the smaller of
    the two without a correction would understate the error rate (fixed).
    Methods in INFO_ONLY_METHODS (tone) are excluded from both: their p-values are not valid on data with spectral
    lines and caused false attributions (R11). They are listed under `info_only`."""
    from scipy import stats
    ps = [r["p"] for m, r in results.items() if m not in INFO_ONLY_METHODS]
    info = sorted(m for m in results if m in INFO_ONLY_METHODS)
    if not ps:
        return {"p_fisher": 1.0, "p_min_bonferroni": 1.0, "decision_methods": [], "info_only": info}
    fisher = float(stats.chi2.sf(-2 * np.sum(np.log(np.maximum(ps, 1e-300))), 2 * len(ps)))
    return {"p_fisher": fisher, "p_min_bonferroni": float(min(1.0, min(ps) * len(ps))),
            "decision_methods": sorted(m for m in results if m not in INFO_ONLY_METHODS), "info_only": info}


def suspect_digest(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""):
            h.update(b)
    return h.hexdigest()
